#reading-list { display: grid; gap: 0.75rem; list-style: none; padding: 0; }

.reading-item { align-items: center; border: 1px solid #cbd5e1; border-radius: 0.5rem; display: flex; gap: 0.75rem; padding: 0.9rem; }

.reading-item label { flex: 1; }

